export const BODY: string = "\n<p>تصویروں سے GIF بنانا مختصر کام ہے: چند تصویریں جمع کریں، انہیں فریم کے طور پر اپ لوڈ کریں، وقت طے کریں اور حرکت ڈاؤن لوڈ کریں۔ یہ رہنما ہر مرحلہ ترتیب سے بتاتا ہے، فریم چننے سے لے کر تیار GIF شیئر کرنے تک۔</p>\n<p>شروع کرنے سے پہلے آپ کو صرف ایک چیز چاہیے: حرکت دینے کے لیے دو یا زیادہ تصویریں۔ وہ تصویریں، اسکرین شاٹ، مصنوعات کے شاٹ یا تصویریں ہو سکتی ہیں۔ ملتے جلتے سائز اور شکلیں ہموار ترین نتیجہ دیتی ہیں، مگر ٹول ملے جلے سائز بھی سنبھالتا ہے۔</p>\n<p><a href=\"/ur/gif-maker/\">GIF میکر</a> کام آپ کے براؤزر میں کرتا ہے۔ کچھ بھی سرور پر اپ لوڈ نہیں ہوتا، کوئی اکاؤنٹ نہیں، اور تیار GIF مفت ڈاؤن لوڈ ہوتا ہے۔ نیچے کے مراحل پر عمل کریں اور چند منٹ میں آپ کے پاس حرکت ہو گی۔</p>\n<h2 id=\"step-1-gather-your-frames\">مرحلہ 1: اپنے فریم جمع کریں</h2>\n<p>وہ تصویریں جمع کریں جو آپ کی GIF کے فریم بنیں گی۔ ردعمل GIF کو تاثر بدلنے والی چند تصویریں چاہییں۔ مصنوعات کے ڈیمو کو مختلف زاویوں سے شاٹ چاہییں۔ سبق کو فی مرحلہ ایک تصویر چاہیے۔</p>\n<p>زیادہ تر GIF کے لیے پانچ سے پندرہ فریم درست حد ہے۔ کم فریم مختصر، تیز حرکت بناتے ہیں، جبکہ زیادہ فریم طویل، ہموار حرکت بناتے ہیں۔ بیس سے زیادہ فریم عام طور پر مطلب ہے کہ GIF ویڈیو بننے کی کوشش کر رہی ہے۔</p>\n<p>جہاں ممکن ہو ملتے جلتے ابعاد والی تصویریں استعمال کریں۔ ایک ہی سائز اور شکل والے فریم ہموار حرکت کرتے ہیں، جبکہ بہت مختلف سائز جھٹکے اور کالے بار بناتے ہیں۔ اگر وہ بہت مختلف ہوں تو پہلے فریم کراپ یا سائز بدلیں۔</p>\n<h2 id=\"step-2-upload-the-frames\">مرحلہ 2: فریم اپ لوڈ کریں</h2>\n<p>GIF میکر کھولیں اور اپنی فریم تصویریں ڈراپ زون پر گھسیٹ دیں، یا اپنے آلے سے چننے کے لیے اس پر کلک کریں۔ آپ سب کچھ ایک ساتھ اپ لوڈ کر سکتے ہیں، یا بعد میں Add Frames کنٹرول سے فریم شامل کر سکتے ہیں اگر درمیان میں مزید تصویریں ملیں۔</p>\n<p>ٹول 20 MB تک JPG، PNG، WebP، HEIC، GIF، BMP اور SVG فائلیں قبول کرتا ہے۔ فون کی تصویریں، اسکرین شاٹ اور گرافکس سب کام کرتے ہیں۔ آئی فون کی HEIC تصویر بغیر کسی اضافی مرحلے کے اپ لوڈ اور بدل جاتی ہے۔</p>\n<p>فریم آپ کے اپ لوڈ کی ترتیب میں دکھائی دیتے ہیں، ایسی فہرست کے طور پر جسے آپ دوبارہ ترتیب دے سکتے ہیں۔ آگے بڑھنے سے پہلے جانچیں کہ آپ کو چاہیے تمام تصویریں موجود ہیں۔ گم شدہ فریم اب شامل کرنا وقت طے ہونے کے بعد شامل کرنے سے آسان ہے۔</p>\n<h2 id=\"step-3-reorder-the-frames\">مرحلہ 3: فریم دوبارہ ترتیب دیں</h2>\n<p>فریموں کو اس ترتیب میں گھسیٹیں جو کہانی بتاتی ہے۔ پہلا فریم وہ ہے جو ناظرین حرکت شروع ہونے سے پہلے دیکھتے ہیں، اور آخری فریم وہ ہے جو وہ لوپ دوبارہ شروع ہونے سے پہلے دیکھتے ہیں، اس لیے دونوں سرے توجہ کے مستحق ہیں۔</p>\n<p>سب سے مضبوط فریم پہلے رکھیں۔ چیٹ یا فیڈ میں پہلا فریم تھمب نیل ہے، اور وہ فیصلہ کرتا ہے کہ کوئی حرکت دیکھے گا یا نہیں۔ پھیکا پہلا فریم مطلب ہے GIF چھوڑ دی جاتی ہے۔</p>\n<p>ترتیب میں جھٹکے جانچیں۔ حرکت میں بعد میں آنے والا فریم اگر فہرست میں پہلے بیٹھا ہو تو حرکت میں نظر آنے والا جھٹکا بناتا ہے۔ فریم فہرست کو سٹوری بورڈ کی طرح پڑھیں اور جو فریم بہاؤ توڑے، اسے منتقل کریں۔</p>\n<h2 id=\"step-4-duplicate-or-remove-frames\">مرحلہ 4: فریم نقل کریں یا ہٹائیں</h2>\n<p>جب آپ وقت کی ترتیبات بدلے بغیر فریم کو زیادہ دیر رکھنا چاہیں تو اسے نقل کریں۔ نقل شدہ عنوان سلائیڈ دوگنی دیر دکھائی دیتی ہے، اور نقل شدہ آخری فریم پیغام کو لوپ دوبارہ شروع ہونے سے پہلے بیٹھنے دیتا ہے۔ نقل کرنا لمحے پر زور دینے کا آسان ترین طریقہ ہے۔</p>\n<p>نقل کرنا حرکت کے اندر لمحہ دہرانے کا طریقہ بھی ہے۔ دو بار دکھایا گیا مصنوعات کا زاویہ توقف کے طور پر پڑھتا ہے، اور دو بار دکھایا گیا ردعمل فریم زور کے طور پر پڑھتا ہے۔ اسے کم استعمال کریں، ورنہ حرکت جھٹکتی لگتی ہے۔</p>\n<p>وہ فریم ہٹا دیں جو معنی شامل کیے بغیر GIF کو سست کرتے ہیں۔ پچھلے فریم کی قریب نقل، دھندلا شاٹ، یا صرف پچھلا فریم دہرانے والا فریم جا سکتا ہے۔ ہر ہٹایا گیا فریم فائل کو چھوٹا اور حرکت کو تنگ بناتا ہے۔</p>\n<h2 id=\"step-5-set-frame-delays\">مرحلہ 5: فریم تاخیر طے کریں</h2>\n<p>فریم تاخیر یہ ہے کہ ہر فریم اسکرین پر کتنی دیر رہتا ہے، اور یہ طے کرتی ہے کہ حرکت کیسا محسوس ہوتی ہے۔ فوری پری سیٹ میں سے ایک سے شروع کریں: 1، 2، 5 یا 10 فریم فی سیکنڈ۔ ڈیمو یا ردعمل کے لیے پانچ فریم فی سیکنڈ عام نقطہ آغاز ہے۔</p>\n<p>پہلے تمام فریموں کے لیے ایک تاخیر طے کریں، پھر ان انفرادی فریموں کو ایڈجسٹ کریں جنہیں زیادہ وقت چاہیے۔ عنوان سلائیڈ کو زیادہ دیر چاہیے تاکہ ناظرین اسے پڑھ سکیں، اور آخری فریم کو زیادہ دیر چاہیے تاکہ پیغام لوپ دوبارہ شروع ہونے سے پہلے بیٹھ جائے۔</p>\n<p>ہر فریم کے لیے یکساں تاخیر GIF وقت میں سب سے عام غلطی ہے۔ اہم فریم بغیر پڑھے تیزی سے گزر جاتے ہیں، جبکہ حرکت والے فریم گھسیٹتے ہیں۔ اہم فریموں کو زیادہ وقت دیں اور حرکت والے فریموں کو کم، اور GIF مکینیکل کی بجائے سوچی سمجھی لگتی ہے۔</p>\n<h2 id=\"step-6-set-the-loop-count\">مرحلہ 6: لوپ گنتی طے کریں</h2>\n<p>چنیں GIF کتنی بار چلے۔ لامحدود لوپ ہمیشہ چلتا ہے، جو ردعمل، سجاوٹ اور بار بار آنکھ پکڑنے والی کسی بھی چیز کو سوٹ کرتا ہے۔ یہ کلاسک GIF رویہ ہے اور پہلے سے طے شدہ انتخاب ہے۔</p>\n<p>محدود لوپ مقررہ تعداد میں چلتا ہے اور پھر آخری فریم پر رک جاتا ہے۔ یہ سبق یا ڈیمو کو سوٹ کرتا ہے جہاں ناظر کو تیار حالت پر ختم ہونا چاہیے۔ دو یا تین کی لوپ گنتی ہمیشہ لوپ کیے بغیر دوسری نظر دیتی ہے۔</p>\n<p>ایک بار چلنا حرکت ایک بار دکھاتا ہے اور رک جاتا ہے۔ یہ انکشاف کو سوٹ کرتا ہے، جیسے پہلے اور بعد جو بعد پر ختم ہونا چاہیے۔ ناظر تبدیلی دیکھتا ہے، پھر نتیجہ اسکرین پر رہتا ہے۔</p>\n<h2 id=\"step-7-choose-frame-fit\">مرحلہ 7: فریم فٹ چنیں</h2>\n<p>فریم فٹ طے کرتا ہے کہ جب آپ کے فریموں کے پہلو تناسب مختلف ہوں تو کیا ہوتا ہے۔ Contain ہر فریم کو آؤٹ پٹ سائز کے اندر بغیر کراپ کے فٹ کرتا ہے، اس لیے پورا فریم نظر آتا ہے اور کوئی بھی خالی جگہ سرحد بن جاتی ہے۔</p>\n<p>Cover فریم کراپ کر کے آؤٹ پٹ سائز مکمل بھر دیتا ہے، اس لیے کوئی خالی پٹیاں نہیں ہوتیں مگر کچھ فریموں کے کنارے کٹ سکتے ہیں۔ یہ کنارے کی تفصیل کھونے کی قیمت پر صاف، مکمل حرکت دیتا ہے۔</p>\n<p>Contain چنیں جب ہر فریم کا ہر حصہ اہم ہو، جیسے سبق جہاں کراپ شدہ بٹن مرحلہ چھپا دے۔ Cover چنیں جب حرکت کو صاف فریم بھرنا ہو، جیسے سوشل پوسٹ جہاں خالی پٹیاں نامکمل لگیں۔</p>\n<h2 id=\"step-8-set-the-output-size\">مرحلہ 8: آؤٹ پٹ سائز طے کریں</h2>\n<p>GIF شیئر کرنے والی جگہ کے لیے آؤٹ پٹ چوڑائی طے کریں۔ تقریباً 480 پکسل چوڑائی چیٹ اور سوشل فیڈ کو سوٹ کرتی ہے، جہاں GIF فون پر دیکھی جاتی ہے۔ بڑی چوڑائی ویب سائٹ یا پریزنٹیشن کو سوٹ کرتی ہے، جہاں GIF بڑی دکھائی جاتی ہے۔</p>\n<p>جب آپ آؤٹ پٹ چوڑائی میں ترمیم کریں تو پہلو تناسب مقرر رہتا ہے، اس لیے چوڑائی بدلنے سے پوری GIF کھینچنے کی بجائے اسکیل ہوتی ہے۔ چوڑائی ایک بار طے کریں اور اونچائی فریموں سے آتی ہے۔</p>\n<p>GIF کے لیے چھوٹا عام طور پر بہتر ہے۔ 480 پکسل چوڑی GIF تیزی سے شیئر کرنے کے لیے کافی چھوٹی اور واضح دیکھنے کے لیے کافی بڑی ہے۔ 1000 پکسل چوڑی GIF کئی گنا فائل سائز ہے، ایسے فرق کے لیے جو زیادہ تر ناظرین محسوس نہیں کریں گے۔</p>\n<h2 id=\"step-9-check-the-live-preview\">مرحلہ 9: براہ راست پیش نظارہ جانچیں</h2>\n<p>Live Timing Preview کھولیں اور حرکت اپنی موجودہ ترتیبات کے ساتھ چلتے ہوئے دیکھیں۔ یہ ایماندارانہ آزمائش ہے: پیش نظارہ تیار وقت، لوپ اور فریم ترتیب بالکل ویسے دکھاتا ہے جیسے ڈاؤن لوڈ شدہ فائل انہیں چلائے گی۔</p>\n<p>تین مسائل دیکھیں: بہت تیز گزرنے والا فریم، جہاں ترتیب ٹوٹے وہ جھٹکا، اور لوپ دوبارہ شروع ہونا جو اچانک لگے۔ پہلا فریم اور آخری فریم طے کرتے ہیں کہ لوپ کتنا ہموار محسوس ہوتا ہے، اس لیے دوبارہ شروع ہونے والے نقطے کو قریب سے دیکھیں۔</p>\n<p>مسائل پیش نظارے میں درست کریں، ڈاؤن لوڈ کے بعد نہیں۔ تاخیر ایڈجسٹ کریں، فریم دوبارہ ترتیب دیں، یا لوپ گنتی بدلیں، پھر پیش نظارہ دوبارہ دیکھیں۔ ہر درست یہاں سیکنڈ لیتا ہے اور بعد میں مکمل دوبارہ بنانا پڑتا ہے۔</p>\n<h2 id=\"step-10-generate-and-download\">مرحلہ 10: بنائیں اور ڈاؤن لوڈ کریں</h2>\n<p>جب پیش نظارہ درست لگے تو GIF بنائیں۔ ٹول فریموں کو آپ کے براؤزر میں معیاری GIF89a فائل میں انکوڈ کرتا ہے، جس میں مختصر GIF کے لیے چند سیکنڈ اور کئی فریم یا اعلیٰ پیلیٹ کوالٹی والی GIF کے لیے زیادہ وقت لگتا ہے۔</p>\n<p>بڑی GIF وارننگ دیکھیں۔ اگر تخمینہ فائل 5 MB یا 15 MB سے گزرے تو ٹول آپ کو بتائے گا۔ پہلے آؤٹ پٹ چوڑائی کم کریں، کیونکہ چوڑائی آدھی کرنے سے پکسل چوتھائی رہ جاتے ہیں، پھر فریم گنتی یا فریم ریٹ کم کریں۔</p>\n<p>تیار فائل ڈاؤن لوڈ کریں، جو animated_compressmypic.gif کے طور پر محفوظ ہوتی ہے۔ شیئر کرنے سے پہلے اس کا نام بامعنی رکھیں، جیسے product-demo.gif یا birthday-reaction.gif، تاکہ بعد میں ڈھونڈنا آسان ہو۔</p>\n<h2 id=\"fixing-a-gif-that-is-too-large\">بہت بڑی GIF درست کرنا</h2>\n<p>بہت بڑی GIF کی عام طور پر تین وجوہات میں سے ایک ہوتی ہے: بہت زیادہ فریم، بہت بڑے ابعاد، یا بہت زیادہ فریم ریٹ۔ انہیں اثر کی ترتیب سے درست کریں، ابعاد سے شروع کریں، جو سب سے بڑی بچت دیتے ہیں۔</p>\n<p>آؤٹ پٹ چوڑائی آدھی کریں اور فائل ڈرامائی طور پر سکڑ جاتی ہے، کیونکہ پکسل گنتی چوتھائی رہ جاتی ہے۔ 480 پکسل چوڑی GIF 960 پکسل والی اسی GIF کے سائز کا چوتھائی ہے، اور فون پر نظر آنے والا فرق چھوٹا ہے۔</p>\n<p>اگلا، فریم گنتی کاٹیں۔ وہ فریم ہٹا دیں جو پچھلے کو دہراتے ہیں یا کہانی میں کم شامل کرتے ہیں۔ ہر ہٹایا گیا فریم فائل سائز میں سیدھی بچت ہے، اور چھوٹی GIF عام طور پر بہتر GIF بھی ہوتی ہے۔</p>\n<h2 id=\"sharing-your-gif\">اپنی GIF شیئر کرنا</h2>\n<p>GIF فائل چیٹ ایپس جیسے واٹس ایپ، ٹیلیگرام، سلیک اور ڈسکارڈ میں سیدھی شیئر کریں، جو سب GIF ان لائن چلاتی ہیں۔ فائل منسلکہ کے طور پر اپ لوڈ کریں یا پیغام میں چسپاں کریں، اور وہ وصول کنندہ کے لیے بغیر کسی اضافی مرحلے کے حرکت کرتی ہے۔</p>\n<p>سوشل پلیٹ فارم پر GIF میڈیا فائل کے طور پر اپ لوڈ کریں۔ زیادہ تر فیڈ GIF اپ لوڈ قبول کرتی ہیں اور انہیں خود بخود چلاتی ہیں، اگرچہ کچھ پس منظر میں GIF کو ویڈیو میں بدل دیتے ہیں۔ حرکت پھر بھی چلتی ہے، اس لیے ناظر کے لیے نتیجہ ایک جیسا ہے۔</p>\n<p>ویب سائٹ پر GIF کو عام تصویر ٹیگ کے ساتھ ایمبیڈ کریں۔ یہ صفحہ لوڈ ہوتے ہی خود بخود چلتی ہے، اس لیے اسے وہاں رکھیں جہاں حرکت قیمت بڑھائے، خلل نہ ڈالے۔ سبق میں GIF آنکھ کو اس مرحلے کی طرف کھینچتی ہے جو وہ دکھاتی ہے۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: GIF چیک لسٹ</h2>\n<p>ملتے جلتے ابعاد والے پانچ سے پندرہ فریم جمع کریں، انہیں اپ لوڈ کریں، انہیں کہانی کی ترتیب میں رکھیں اور زور چاہنے والے فریم نقل کریں۔ پانچ فریم فی سیکنڈ کے قریب بنیادی تاخیر طے کریں، عنوان اور آخری فریم لمبے کریں، اور سیاق کے لیے لوپ چنیں۔</p>\n<p>منزل کے لیے آؤٹ پٹ چوڑائی طے کریں، ملے جلے سائز والے فریموں کے لیے Contain یا Cover چنیں، اور بنانے سے پہلے Live Timing Preview جانچیں۔ بڑی GIF وارننگ پر دھیان دیں اور پہلے چوڑائی سکڑائیں۔</p>\n<p>مکمل رہنما کے لیے <a href=\"/ur/blog/gif-maker-rehnumai/\">GIF Maker: Complete Guide</a> پڑھیں، اور سائز تجارت کی تفصیل کے لیے <a href=\"/ur/blog/gif-frame-rate-file-size/\">GIF Frame Rate and File Size: Smooth vs Small</a> دیکھیں۔ اپنی GIF <a href=\"/ur/gif-maker/\">GIF میکر</a> سے بنائیں۔</p>\n";

